"""Issues 07-08: data/index.json is generated by catalogue.py and stays in sync."""
import json
import sys
import unittest
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
sys.path.insert(0, str(ROOT / 'scripts'))
import catalogue  # noqa: E402


def rendered_index():
    data = catalogue.read('data/ghosts.json')
    sources = {s['id']: s for s in catalogue.read('data/references.json')['references'] + catalogue.read('research/evidence.json')['sources']}
    outputs = catalogue.render(data, sources)
    assert 'data/index.json' in outputs, 'render() does not emit data/index.json'
    return data, json.loads(outputs['data/index.json']), outputs['data/index.json']


class Index(unittest.TestCase):
    def test_index_lists_every_ghost(self):
        data, index, _ = rendered_index()
        self.assertEqual([e['id'] for e in index['ghosts']], [g['id'] for g in data['ghosts']])
        for entry, ghost in zip(index['ghosts'], data['ghosts']):
            self.assertEqual(entry['name'], ghost['name'])
            self.assertEqual(entry['aliases'], ghost['aliases'])
            self.assertEqual(entry['research_status'], ghost['research_status'])
            self.assertEqual(entry['classification'], ghost['claims']['classification']['value'])
            self.assertEqual(entry['location'], ghost['claims']['location']['value'])
            self.assertEqual(entry['page'], f'ghosts/{ghost["id"]}.md')

    def test_committed_index_is_in_sync(self):
        _, _, text = rendered_index()
        path = ROOT / 'data/index.json'
        self.assertTrue(path.exists(), 'data/index.json not committed')
        self.assertEqual(path.read_text(encoding='utf-8'), text)

    def test_index_links_research_dossier(self):
        _, index, _ = rendered_index()
        for entry in index['ghosts']:
            dossier = f'research/ghosts/{entry["id"]}.md'
            expected = dossier if (ROOT / dossier).exists() else None
            self.assertEqual(entry['research_file'], expected, entry['id'])


if __name__ == '__main__':
    unittest.main()
